// AUTO-GENERATED — do not hand-edit. Baked from a real Copernicus GLO-30 DEM + OpenStreetMap
// buildings for Boulder, Colorado over a 2000 m × 1200 m window
// (160×96 cells @ 12.5 m). Elevation is normalised 0..1000 (int16); real range
// is REAL_MIN..REAL_MAX metres. Flags per cell: bit0 = building, bit1 = water (Boulder Creek).
export const CITY_W = 160;
export const CITY_H = 96;
export const CITY_LABEL = 'Boulder, Colorado';
export const CITY_REAL_MIN = 1610.9;
export const CITY_REAL_MAX = 1663.3;
export const CITY_SIZE_M = 2000;

const Z16_B64 = '';
const FLAGS_B64 = '';

function bytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export interface CityData { zNorm: Float32Array; building: Uint8Array; water: Uint8Array }

/** Decode the baked city: zNorm in 0..1 (multiply by a target relief), building + water masks. */
export function decodeCity(): CityData {
  const z16 = new Int16Array(bytes(Z16_B64).buffer);
  const flags = bytes(FLAGS_B64);
  const n = CITY_W * CITY_H;
  const zNorm = new Float32Array(n);
  const building = new Uint8Array(n);
  const water = new Uint8Array(n);
  for (let i = 0; i < n; i++) {
    zNorm[i] = z16[i] / 1000;
    building[i] = flags[i] & 1 ? 1 : 0;
    water[i] = flags[i] & 2 ? 1 : 0;
  }
  return { zNorm, building, water };
}
